	// Simulate a directory path and a malicious filename
	dirPath := "sensitive_data"
	filename := "../../etc/passwd"  // Attempting to access a sensitive file

	filePath := fmt.Sprintf("%s/%s", dirPath, filename)
	cleanedPath := filepath.Clean(filePath)

	fmt.Printf("Original Path: %s\n", filePath)
	fmt.Printf("Cleaned Path: %s\n", cleanedPath)

	// Check if the cleaned path still points to the sensitive file
	if cleanedPath == "etc/passwd" {
		fmt.Println("Path traversal vulnerability detected!")
	} else {
		fmt.Println("Path traversal attack prevented.")
